// Classify every post as Reel / Photo / Video (dropping plain text/link
// posts, which aren't in scope) and carry the account context forward.
// Reels still need a separate insights call for play counts; Photos and
// Videos already have likes/comments/shares from the fields above.
const ctx = $('When Executed by Parent').first().json;
const posts = $input.first().json.data || [];
const out = [];

for (const p of posts) {
  const att = p.attachments && p.attachments.data ? p.attachments.data[0] : null;
  const url = p.permalink_url || (att && att.url) || '';
  const m = url.match(/reel\/(\d+)/);
  const reelId = (att && att.target && att.target.id) || (m ? m[1] : null);
  const isReel = url.includes('/reel/') && !!reelId;

  const attType = (att && (att.media_type || att.type)) || null;
  const type = isReel ? 'Reel'
    : attType === 'photo' || attType === 'album' ? 'Photo'
    : attType === 'video' || attType === 'video_inline' || attType === 'video_autoplay' || attType === 'video_direct_response' ? 'Video'
    : null;

  if (!type) continue; // out of scope: plain text/status/link posts

  out.push({
    json: {
      platform: 'Facebook',
      channel: ctx.channel,
      account_id: ctx.account_id,
      likes_label: ctx.likes_label || 'Reactions',
      post_id: p.id,
      reel_id: isReel ? String(reelId) : null,
      is_reel: isReel,
      type,
      title: (p.message || (att && att.title) || `Facebook ${type}`).split('\n')[0].slice(0, 60),
      permalink: url,
      created_at: p.created_time || null,
      likes: (p.likes && p.likes.summary) ? p.likes.summary.total_count : null,
      comments: (p.comments && p.comments.summary) ? p.comments.summary.total_count : null,
      shares: p.shares ? (p.shares.count || 0) : 0,
    },
    pairedItem: 0,
  });
}

return out;

// Pair insights back to reels via pairedItem (never by raw array index)
// -> a single failed request can no longer shift the metrics of other reels.
const reels = $('Extract posts').all();
const items = $input.all();

function srcIndex(item, fallback) {
  const pi = item.pairedItem;
  if (typeof pi === 'number') return pi;
  if (Array.isArray(pi) && pi.length) return pi[0].item;
  if (pi && typeof pi === 'object' && pi.item !== undefined) return pi.item;
  return fallback;
}

function findMetric(list, name) {
  return (list || []).find(m => m.name === name);
}

function sumAll(metric) {
  const v = metric && metric.values && metric.values[0] ? metric.values[0].value : null;
  if (v === null || v === undefined) return 0;
  if (typeof v === 'object') return Object.values(v).reduce((s, n) => s + Number(n || 0), 0);
  return Number(v) || 0;
}

function pickKey(metric, key) {
  const v = metric && metric.values && metric.values[0] ? metric.values[0].value : null;
  if (v && typeof v === 'object') return Number(v[key] || 0);
  return 0;
}

const rows = items.map((item, i) => {
  const reel = (reels[srcIndex(item, i)] || {}).json || {};
  const data = (item.json && item.json.data) || [];
  const ok = !(item.json && item.json.error) && data.length > 0;

  return {
    json: {
      platform: 'Facebook',
      channel: reel.channel,
      account_id: reel.account_id,
      likes_label: reel.likes_label || 'Reactions',
      id: String(reel.reel_id || reel.post_id || ''),
      title: reel.title || 'Facebook Reel',
      type: 'Reel',
      views: sumAll(findMetric(data, 'fb_reels_total_plays')),
      likes: sumAll(findMetric(data, 'post_video_likes_by_reaction_type')),
      comments: pickKey(findMetric(data, 'post_video_social_actions'), 'comment'),
      shares: pickKey(findMetric(data, 'post_video_social_actions'), 'share'),
      permalink: reel.permalink || '',
      created_at: reel.created_at || null,
      insights_ok: ok,
    },
    pairedItem: 0,
  };
});

return rows.filter(r => r.json.id);

// Photos and Videos already have likes/comments/shares fetched directly
// alongside the post itself (see "Get page posts" fields) -- no separate
// insights call needed here, unlike Reels which require /video_insights
// for play counts.
return $input.all().map(item => {
  const p = item.json;

  return {
    json: {
      platform: 'Facebook',
      channel: p.channel,
      account_id: p.account_id,
      likes_label: p.likes_label,
      id: String(p.post_id),
      title: p.title,
      type: p.type,
      views: null,
      likes: p.likes,
      comments: p.comments,
      shares: p.shares,
      permalink: p.permalink,
      created_at: p.created_at,
      insights_ok: p.likes != null || p.comments != null,
    },
    pairedItem: 0,
  };
});

// Merge (multi-input) as the sub-workflow's terminal node tags each item
// with pairedItem: { item: 0, input: 1 } for anything that arrived via its
// second input -- but the parent's Execute Workflow node only has ONE
// input, so that reference is invalid there and crashes n8n's engine
// (assignPairedItems). Flattening pairedItem back to a plain 0 here, as
// the new terminal node, avoids ever exporting that invalid reference.
return $input.all().map(item => ({ json: item.json, pairedItem: 0 }));
